cypress_script:
describe('HTTP Status Code Pages', () => {
  it('should navigate to 200 status code page', () => {
    cy.visit('https://the-internet.herokuapp.com/status_codes');
    cy.contains('200').click();
    cy.url().should('include', '/status_codes/200');
  });
  it('should navigate to 404 status code page', () => {
    cy.visit('https://the-internet.herokuapp.com/status_codes');
    cy.contains('404').click();
    cy.url().should('include', '/status_codes/404');
  });
});

playwright_script:
import { test } from '@playwright/test';

test.describe('HTTP Status Code Pages', () => {
  test('should navigate to 200 status code page', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/status_codes');
    await page.click('text=200');
    await page.waitForURL('**/status_codes/200');
  });
  test('should navigate to 404 status code page', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/status_codes');
    await page.click('text=404');
    await page.waitForURL('**/status_codes/404');
  });
});
